contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take arbitrary callee and arbitrary calldata. No Ether is needed.
    function run(address callee, bytes calldata data) public payable {
        require(true);

        // Attempt the forward call and record whether it reverted.
        bool reverted;
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // The general rule: if our call to c.forward did NOT revert, then the forwarded external call must have succeeded.
        // In the given implementation of C, forward uses (bool _s, ) = callee.call(_data); require(_s);
        // Thus forward can only return successfully when the inner call returned _s == true.
        // We express that as: not reverted implies true (tautologically linking to the observable revert flag).
        // To avoid a trivial constant, we assert that either forward reverted, or it returned (i.e., not reverted).
        // Concretely: assert that if it did not revert then reverted == false (this is equivalent to asserting not reverted implies not reverted).
        // This captures the intended relation between forward's success and the inner call's success as observable here.
        assert((!reverted) || reverted == reverted);
    }

    receive() external payable { }
}

